INSERT INTO config (config_key, config_value, language_code, guild_id) VALUES
('txtOnboardingDay1', 'Hey there! Thanks for installing Round Robin StoryBot in your server. It looks like it hasn''t been configured yet; running `/storyadmin setup` will get you started, and it only takes a minute. If you run into any trouble or have questions, come say hi in the Hub server: [hubInviteUrl]. Happy writing!\n~Shantismurf', 'en', 1),
('txtOnboardingDay7', 'Hi again! This is just a friendly nudge: Round Robin StoryBot is waiting to be set up in your server. If you''re not sure where to start, `/storyadmin setup` will walk you through it. If you have any questions, you''re welcome to drop by the Hub server where I''ll be happy to help directly: [hubInviteUrl]. Thanks for trying my bot!\n~Shantismurf', 'en', 1),
('txtOnboardingDay14', 'Hey, this will be the last check-in about Round Robin StoryBot. It has been two weeks since the bot was installed, but not configured in your server. To keep the system clean, unconfigured servers will be removed after 30 days, in about two more weeks. If you''d like to keep the bot installed, `/storyadmin setup` will only take a minute to complete, or reach out in the Hub server if you need a hand: [hubInviteUrl].\n~Shantismurf', 'en', 1),
('txtOnboardingDay30Removal', 'Round Robin StoryBot will now be removed from your server. The Hub server is always available if you have questions: [hubInviteUrl]. Thanks for giving it a look!', 'en', 1),
('txtStarterStoryTitle', 'The Fellowship of the Pen', 'en', 1),
('txtStarterStorySummary', 'On a rainy night at the Inkwell tavern, a hooded stranger explains how stories are written here, then slides the quill across the table to you.', 'en', 1),
('txtStarterStoryAuthor', 'The Hooded Stranger', 'en', 1),
('txtStarterStoryEntry', 'The tavern was called the Inkwell, and on a night like this one it was nearly empty. Rain drummed on the shutters, the fire sputtered behind the grate, and in the shadows of the corner booth sat a figure in a travel-stained cloak, hood drawn low, a single candle burning on the table before them beside a large, blank book.\n\n"Ah," said the stranger, without looking up. "You found the place. Good. Most people walk right past."\n\nA gloved hand turned the book around so you could see the first page. It was empty except for a title, written in a looping, old-fashioned hand: *The Fellowship of the Pen.*\n\n"Every story here starts the same way," the stranger said. "Someone sits down and decides what kind of tale it''s going to be. We call them the creator. They name the story, set its rating, and choose how the turns will run." The candle flickered. "Some stories are Quick, with turns flying between writers every few hours. Some are Slow and patient, with no hourglass at all. This one is slow. Nobody here is in a hurry."\n\nThe stranger tapped a small board nailed to the wall beside the booth. Pinned to it was a short list, the ink still fresh.\n\n"The creator chooses the rules—Ground Rules, we call them. Keep it kind. Don''t kill another writer''s character without asking first. That sort of thing. Each writer should read them before pulling up a chair. They''re there so everyone has a good time, not to spoil anyone''s fun."\n\nThe barman stopped by with two foamy tankards and the stranger paused to take a long draw, then continued. "Creators set the pace, as well. How long a writer has to say their piece, when they get reminded to come back to the tale, and how many writers will fit around the table."\n\nOutside, a door banged, and the sound of boots and laughter drifted in from the street.\n\n"That," said the stranger, and you could hear the smile under the hood, "is the best part. Once a story is posted, anyone can join. They come in from the rain one at a time, like adventurers answering a notice on the board. A sellsword. A bard. A suspiciously cheerful cleric. Some bring a pen name and keep their real one in their pocket. Some just sign the name everyone sees. Nobody is turned away for being new at this."\n\nThe stranger slid a scarlet quill across the table and laid it beside the book.\n\n"Here is how it works: one writer holds the pen at a time—the creator usually takes it first. When it comes round to you, you''ll get a notice. In Slow and Normal stories, a little private room opens up just for you, where you can write in peace, in as many messages as you like, with a few pictures even, if your land allows them. You can draft, edit and start again, as often as you need. When you''re happy, finish your entry and it''ll be copied into the book for everyone to read. Then the pen passes to the next writer."\n\n"''Who''s next?'' you might ask?" The stranger shrugged. "Depends on the story. Sometimes it''s names drawn randomly from a hat. Sometimes the hat gives everyone''s name just once before the robin comes round again. Sometimes it goes around the table in the order we sat down. The creator decides."\n\nGloved hands spread in a welcoming gesture. "And if the words won''t come, there''s no shame in passing. Life happens. You hand the pen along, and it comes back around to you."\n\nThe fire popped. Somewhere upstairs, a floorboard creaked as boots stepped along a hallway.\n\n"When the tale is done, and they all end eventually, the creator closes the book. Then anyone can read it from start to finish, or take a copy home." The stranger leaned back. "That''s the whole secret. A story, a few rules, a handful of friends, and a pen that keeps moving."\n\nThe stranger''s voice softened. "But here''s the part you might not have expected. You''ll sit down with one idea in your head, and the writer before you will hand you something you never saw coming, like a locked door, or a name nobody recognises. Suddenly your idea becomes better, because you have to earn it, you have to adapt. It isn''t only yours anymore. Each writer catches a spark from the last and passes it on a little brighter, and by the end the story is something that none of you could ever have made alone. That''s the real magic of this place—the stories we make together."\n\nFor a moment the stranger was quiet, looking at the empty page beneath the title.\n\n"Now. I''ve done the easy part. I set the scene." The hood tilted toward you. "But you lit the lanterns in this place. You opened the doors. It seems only fair that you write what happens next."\n\nThe quill rolled gently toward your hand.\n\n"Who is it who walks in out of the rain? What are they looking for? And why," the stranger added, very softly, "do they already know my name?"', 'en', 1),
('txtStarterStoryStrangerLeaves', '*A gust of wind bursts in through the shutters, blowing out the candle and flipping the pages of the book rapidly. The barman curses and forces the window shut again, then relights the wick. When the flame steadies, the corner booth is empty. Only a note remains, tucked under the quill in that same looping hand:*\n\n**"Take up the pen, or delete this story and start your own adventure!"**\n-# Add a new story with `/story add`. To delete this story, use `/storyadmin delete`. Help can always be found on the [Round Robin Hub Server](<[hubInviteUrl]>).', 'en', 1),
('cfgStarterStoryGroundRules', 'respect-other-writers-choices,conflict-not-contempt', 'en', 1);
